def play(board, r, c, color):
    n = len(board)
    if board[r][c] != '.':
        return [[], 0]
    b = [list(row) for row in board]
    b[r][c] = color
    other = 'O'
    if color == 'O':
        other = 'X'
    captured = 0
    for dr, dc in [[-1, 0], [1, 0], [0, -1], [0, 1]]:
        y = r + dr
        x = c + dc
        if 0 <= y < n and 0 <= x < n and b[y][x] == other:
