practice.solution:
def area_score(board, komi):
    n = len(board)
    black = 0
    white = 0
    seen = []
    for r in range(n):
        for c in range(n):
            ch = board[r][c]
            if ch == 'X':
                black += 1
            elif ch == 'O':
                white += 1
            elif [r, c] not in seen:
                region = [[r, c]]
                seen.append([r, c])
                stack = [[r, c]]
                touch = []
                while stack:
                    p = stack.pop()
                    for dr, dc in [[-1, 0], [1, 0], [0, -1], [0, 1]]:
                        y = p[0] + dr
                        x = p[1] + dc
                        if 0 <= y < n and 0 <= x < n:
                            q = board[y][x]
                            if q == '.':
                                if [y, x] not in seen:
                                    seen.append([y, x])
                                    region.append([y, x])
                                    stack.append([y, x])
                            elif q not in touch:
                                touch.append(q)
                if touch == ['X']:
                    black += len(region)
                elif touch == ['O']:
                    white += len(region)
    return [black, white, black - white - komi]

