def flat_mc(stones, playouts, seed):
    x = seed
    wins = []
    for m in range(1, min(3, stones) + 1):
        w = 0
        for g in range(playouts):
            left = stones - m
            me_to_move = False
            if left == 0:
                w += 1
                continue
            while True:
                k = min(3, left)
                x = (75 * x + 74) % 65537
                take = 1 + x % k
                left -= take
                if left == 0:
                    if me_to_move:
                        w += 1
                    break
                me_to_move = not me_to_move
        wins.append(w)
    return wins

