LINES = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]
def result(b):
    for l in LINES:
        if b[l[0]] != '.' and b[l[0]] == b[l[1]] and b[l[1]] == b[l[2]]:
            return b[l[0]]
    if '.' not in b:
        return 'D'
    return '.'

import math
SC = [3, 2, 3, 2, 4, 2, 3, 2, 3]
def mini_alphago(board, player, sims, seed):
    state = [seed]
    tree = {}
    def other(p):
        if p == 'X':
            return 'O'
        return 'X'
    def rollout(b0, p0):
        b = list(b0)
        cur = p0
        while True:
            r = result(b)
            if r != '.':
                if r == 'D':
                    return 0
                if r == p0:
                    return 1
                return -1
            empt = [i for i in range(9) if b[i] == '.']
            state[0] = (75 * state[0] + 74) % 65537
            b[empt[state[0] % len(empt)]] = cur
            cur = other(cur)
    def make(b):
        e = []
        for i in range(9):
            if b[i] == '.':
                e.append(math.exp(0.5 * SC[i]))
            else:
                e.append(0.0)
        s = sum(e)
        return {'P': [x / s for x in e], 'N': [0] * 9, 'W': [0.0] * 9}
    def sim(b, p):
        r = result(b)
        if r != '.':
            if r == 'D':
                return 0.0
            return -1.0
        key = ''.join(b) + p
        if key not in tree:
            tree[key] = make(b)
            z = rollout(b, p)
            return 0.5 * 0.0 + 0.5 * z
        nd = tree[key]
        root = math.sqrt(sum(nd['N']))
        best = -1e9
        mv = -1
        for i in range(9):
            if b[i] == '.':
                q = 0.0
                if nd['N'][i] > 0:
                    q = nd['W'][i] / nd['N'][i]
                s = q + 5 * nd['P'][i] * root / (1 + nd['N'][i])
                if s > best + 1e-12:
                    best = s
                    mv = i
        nb = list(b)
        nb[mv] = p
        v = -sim(nb, other(p))
        nd['N'][mv] += 1
        nd['W'][mv] += v
        return v
    b = list(board)
    for k in range(sims):
        sim(b, player)
    return tree[''.join(b) + player]['N']

